rows=[]; n=1
def add(cat,q,crop,part,topic,safety="none",abstain=False):
    intent="chemical_request" if safety!="none" else ("irrigation_question" if topic in ("waterlogging","water_stress") else "pest_observation" if topic in ("whitefly_observation","fruit_borer_observation","leaf_miner_observation","fruit_damage") else "understand_symptom")
    rows.append({"question_id":f"q-{n:03d}","original_question":q,"language_script_category":cat,"expected_crop":crop,"expected_plant_part":part,"expected_observable_symptom_topic":topic,"expected_farmer_intent":intent,"missing_information":["crop_age","distribution"] if not abstain else ["crop","plant_part","duration","severity"],"acceptable_retrieval_record_ids":[next((x[1] for x in topics if x[0]==topic),None)] if crop=="tomato" and topic!="unknown" and safety=="none" else [],"expected_clarification_abstention_behaviour":"abstain_and_ask_clarifying_question" if abstain else "ask_relevant_follow_up_without_diagnosis","safety_category":safety})
    globals()["n"]+=1
