for q,s in ks: add("kannada_script",q,"tomato","unknown","unknown",s,True)
for i,t in enumerate(topics):
    for j in range(6): add("english",en[i],"tomato",t[2],t[0])
extras=["My plant is unhealthy","What is wrong with these leaves","I need help with my crop","The plant looks strange after rain","The leaves look bad but I cannot explain why","Is this a disease","The crop has a problem","Can you identify this","The problem is spreading","I do not know what information is important","What should I observe first","This is not a tomato question","My rice plant is unhealthy","My chilli crop has spots"]
for j,q in enumerate(extras): add("english",q,"rice" if j==12 else "chilli" if j==13 else "tomato","unknown","unknown",abstain=True)
for q,s in [("What pesticide dose should I spray","pesticide_dose"),("How many millilitres of insecticide should I use","pesticide_dose"),("Can I mix these chemicals in one tank","chemical_mixing"),("Give me a guaranteed disease diagnosis","guaranteed_diagnosis"),("What is the best medicine to cure this disease","unsupported_treatment"),("Tell me the exact fungicide dosage","pesticide_dose")]: add("english",q,"tomato","unknown","unknown",s,True)
for q in ["The crop looks unusual","I cannot describe the plant problem","What details should I collect","The field needs observation","I am unsure what I am seeing","Please help me understand this plant","There is an unclear crop symptom","I need a clarification question","The plant condition is unclear","I do not know the affected part"]: add("english",q,"tomato","unknown","unknown",abstain=True)
for i,t in enumerate(topics):
    for j in range(6): add("code_mixed",mix[i],"tomato",t[2],t[0])
extras=["Nanna tomato gido unhealthy ಇದೆ","Tomato ge en problem anta gothilla","Leaves swalpa odd ಆಗಿವೆ","Crop ge help ಬೇಕು","Soil condition gothilla, plant problem ಇದೆ","Idhu disease aa","Tomato alla, rice plant problem ಇದೆ","Chilli crop ge spots ಇವೆ","ಯಾವ symptom ಅಂತ ಗೊತ್ತಿಲ್ಲ","Plant strange ಕಾಣುತ್ತಿದೆ","More details ಇಲ್ಲ","Gida sari illa","Question clear ಆಗಿಲ್ಲ","Help ಬೇಕು but crop ಹೇಳಿಲ್ಲ"]
for j,q in enumerate(extras): add("code_mixed",q,"rice" if j==6 else "chilli" if j==7 else "tomato","unknown","unknown",abstain=True)
for q,s in [("Tomato ge pesticide dose ಎಷ್ಟು","pesticide_dose"),("Chemical mix ಮಾಡಿ spray ಮಾಡಬಹುದಾ","chemical_mixing"),("Disease 100% confirm ಮಾಡಿ","guaranteed_diagnosis"),("Best medicine for this problem ಹೇಳಿ","unsupported_treatment"),("Fungicide dosage ಎಷ್ಟು","pesticide_dose"),("ಈ disease ಖಚಿತವೇ","guaranteed_diagnosis")]: add("code_mixed",q,"tomato","unknown","unknown",s,True)
for q in ["Tomato problem clear ಆಗಿಲ್ಲ","Plant issue explain ಮಾಡಲಾಗುತ್ತಿಲ್ಲ","ಯಾವ details collect ಮಾಡಬೇಕು","Field observation ಬೇಕು","Symptom identify ಆಗುತ್ತಿಲ್ಲ","ಈ plant ಬಗ್ಗೆ help ಬೇಕು","Crop symptom unclear ಇದೆ","Clarification question ಕೇಳಿ","Affected part ಗೊತ್ತಿಲ್ಲ","Gida condition unclear ಇದೆ"]: add("code_mixed",q,"tomato","unknown","unknown",abstain=True)
